// src/composables/useToolbar.js
import { ref } from 'vue';

export function useToolbar(canvasEl) {
    const zoomLevel = ref(100);
    const MIN_ZOOM = 25;
    const MAX_ZOOM = 300;
    const STEP = 10;

    // CSS transform 縮放：只改視覺，不動畫布資料
    const _applyZoom = () => {
        const el = canvasEl.value;
        if (!el) return;
        el.style.transform = `scale(${zoomLevel.value / 100})`;
        el.style.transformOrigin = 'center center';
    };

    const zoomIn = () => {
        zoomLevel.value = Math.min(MAX_ZOOM, zoomLevel.value + STEP);
        _applyZoom();
    };

    const zoomOut = () => {
        zoomLevel.value = Math.max(MIN_ZOOM, zoomLevel.value - STEP);
        _applyZoom();
    };

    const resetView = () => {
        zoomLevel.value = 100;
        _applyZoom();
    };

    const fitScreen = (wrapperEl) => {
        if (!canvasEl.value || !wrapperEl) return;
        const ww = wrapperEl.clientWidth - 80;
        const wh = wrapperEl.clientHeight - 80;
        const cw = canvasEl.value.width;
        const ch = canvasEl.value.height;
        const scale = Math.min(ww / cw, wh / ch, 1);
        zoomLevel.value = Math.round(scale * 100);
        _applyZoom();
    };

    return { zoomLevel, zoomIn, zoomOut, resetView, fitScreen };
}
