<template>
    <div v-if="objectType" class="obj-props">
        <!-- ── 文字內容（文字專用）── -->
        <div v-if="objectType === 'text'" class="form-group">
            <label>文字內容</label>
            <textarea
                :value="props.text"
                class="form-control"
                rows="3"
                @input="emit('update', { text: $event.target.value })"
            ></textarea>
        </div>

        <!-- ── 字型 & 大小（文字專用）── -->
        <div v-if="objectType === 'text'" class="form-row">
            <div class="form-group">
                <label>字型</label>
                <select
                    :value="props.fontFamily"
                    class="form-control"
                    @change="emit('update', { fontFamily: $event.target.value })"
                >
                    <option value="Microsoft JhengHei">微軟正黑體</option>
                    <option value="Arial">Arial</option>
                    <option value="Times New Roman">Times New Roman</option>
                    <option value="Georgia">Georgia</option>
                    <option value="Courier New">Courier New</option>
                </select>
            </div>
            <div class="form-group">
                <label>大小</label>
                <input
                    :value="props.fontSize"
                    type="number"
                    class="form-control"
                    min="8"
                    max="300"
                    @input="emit('update', { fontSize: Number($event.target.value) })"
                />
            </div>
        </div>

        <!-- ── 粗體/斜體（文字專用）── -->
        <div v-if="objectType === 'text'" class="form-group">
            <label>樣式</label>
            <div class="toggle-row">
                <button
                    :class="['style-btn', { active: props.bold }]"
                    @click="emit('update', { bold: !props.bold })"
                >
                    <b>B</b>
                </button>
                <button
                    :class="['style-btn', { active: props.italic }]"
                    @click="emit('update', { italic: !props.italic })"
                >
                    <i>I</i>
                </button>
            </div>
        </div>

        <!-- ── 文字顏色（文字專用）── -->
        <div v-if="objectType === 'text'" class="form-group">
            <label>文字顏色</label>
            <div class="color-row">
                <input
                    :value="props.color"
                    type="color"
                    class="color-input"
                    @input="emit('update', { color: $event.target.value })"
                />
                <span class="color-value">{{ props.color }}</span>
            </div>
        </div>

        <!-- ── 分隔線 ── -->
        <div class="divider"></div>

        <!-- ── 旋轉 ── -->
        <div class="form-group">
            <label>旋轉角度：{{ props.rotation }}°</label>
            <div class="slider-row">
                <input
                    :value="props.rotation"
                    type="range"
                    min="0"
                    max="360"
                    step="1"
                    class="slider"
                    @input="emit('update', { rotation: Number($event.target.value) })"
                />
                <input
                    :value="props.rotation"
                    type="number"
                    class="form-control num-input"
                    min="0"
                    max="360"
                    @input="emit('update', { rotation: Number($event.target.value) })"
                />
            </div>
        </div>

        <!-- ── 透明度 ── -->
        <div class="form-group">
            <label>透明度：{{ props.opacity }}%</label>
            <input
                :value="props.opacity"
                type="range"
                min="0"
                max="100"
                step="1"
                class="slider"
                @input="emit('update', { opacity: Number($event.target.value) / 100 })"
            />
        </div>

        <!-- ── 寬高（手動輸入）── -->
        <div class="form-row">
            <div class="form-group">
                <label>寬度</label>
                <input
                    :value="props.width"
                    type="number"
                    class="form-control"
                    min="10"
                    @input="emit('update', { width: Number($event.target.value) })"
                />
            </div>
            <div class="form-group">
                <label>高度</label>
                <input
                    :value="props.height"
                    type="number"
                    class="form-control"
                    min="10"
                    @input="emit('update', { height: Number($event.target.value) })"
                />
            </div>
        </div>

        <!-- ── 位置 ── -->
        <div class="form-row">
            <div class="form-group">
                <label>X</label>
                <input
                    :value="props.x"
                    type="number"
                    class="form-control"
                    @input="emit('update', { x: Number($event.target.value) })"
                />
            </div>
            <div class="form-group">
                <label>Y</label>
                <input
                    :value="props.y"
                    type="number"
                    class="form-control"
                    @input="emit('update', { y: Number($event.target.value) })"
                />
            </div>
        </div>

        <!-- ── 圖片濾鏡（圖片專用）── -->
        <template v-if="objectType === 'image'">
            <div class="divider"></div>
            <div class="form-group">
                <label>亮度：{{ props.brightness }}</label>
                <input
                    :value="props.brightness"
                    type="range"
                    min="-100"
                    max="100"
                    step="1"
                    class="slider"
                    @input="emit('update', { brightness: Number($event.target.value) })"
                />
            </div>
            <div class="form-group">
                <label>對比：{{ props.contrast }}</label>
                <input
                    :value="props.contrast"
                    type="range"
                    min="-100"
                    max="100"
                    step="1"
                    class="slider"
                    @input="emit('update', { contrast: Number($event.target.value) })"
                />
            </div>
        </template>

        <!-- ── 刪除按鈕 ── -->
        <button class="delete-btn btn" @click="emit('delete')">
            <i class="fas fa-trash-alt"></i>
            刪除物件
        </button>
    </div>

    <!-- 未選取提示 -->
    <div v-else class="no-select">
        <i class="fas fa-mouse-pointer"></i>
        <span>點選畫布物件<br />以編輯屬性</span>
    </div>
</template>

<script setup>
    defineProps({
        objectType: { type: String, default: null },
        props: { type: Object, default: () => ({}) }
    });

    const emit = defineEmits(['update', 'delete']);
</script>

