// src/composables/useCanvas.js
/**
 * 純原生 Canvas 2D 引擎
 * 支援：文字物件、圖片物件
 * 操作：選取、拖曳、縮放把手、旋轉把手
 */
import { ref } from 'vue';

// ─── 內部工具 ─────────────────────────────────────
const DEG = Math.PI / 180;

function rotatePoint(cx, cy, x, y, angleDeg) {
    const rad = angleDeg * DEG; // ← 拿掉負號
    const cos = Math.cos(rad);
    const sin = Math.sin(rad);
    return {
        x: cos * (x - cx) - sin * (y - cy) + cx,
        y: sin * (x - cx) + cos * (y - cy) + cy
    };
}
// localPoint 用於 hitTest：需要反向轉回本地座標（負號在這裡）
function localPoint(obj, px, py) {
    const cx = obj.x + obj.width / 2;
    const cy = obj.y + obj.height / 2;
    // ★ hitTest 需要「反轉」座標，所以傳入負角度
    return rotatePoint(cx, cy, px, py, -obj.rotation);
}
function hitTest(obj, px, py) {
    const lp = localPoint(obj, px, py);
    return (
        lp.x >= obj.x && lp.x <= obj.x + obj.width && lp.y >= obj.y && lp.y <= obj.y + obj.height
    );
}

// ─── 把手定義 ─────────────────────────────────────
const HANDLE_SIZE = 8;
const ROTATE_OFFSET = 24;

function getHandles(obj) {
    const { x, y, width, height, rotation } = obj;
    const cx = x + width / 2;
    const cy = y + height / 2;

    const corners = [
        { id: 'tl', lx: x, ly: y },
        { id: 'tr', lx: x + width, ly: y },
        { id: 'br', lx: x + width, ly: y + height },
        { id: 'bl', lx: x, ly: y + height }
    ];

    // 旋轉把手（上方中心）
    const rotHandle = rotatePoint(cx, cy, cx, y - ROTATE_OFFSET, rotation);

    return {
        corners: corners.map((c) => {
            const p = rotatePoint(cx, cy, c.lx, c.ly, rotation);
            return { id: c.id, x: p.x, y: p.y };
        }),
        rotate: { id: 'rotate', x: rotHandle.x, y: rotHandle.y }
    };
}

function hitHandle(handles, px, py, radius = HANDLE_SIZE + 2) {
    for (const h of handles.corners) {
        const dx = h.x - px,
            dy = h.y - py;
        if (dx * dx + dy * dy <= radius * radius) return h.id;
    }
    const dr = handles.rotate;
    const dx = dr.x - px,
        dy = dr.y - py;
    if (dx * dx + dy * dy <= (radius + 2) * radius) return 'rotate';
    return null;
}

// ─── 繪製 ─────────────────────────────────────────
function renderObject(ctx, obj) {
    ctx.save();
    const cx = obj.x + obj.width / 2;
    const cy = obj.y + obj.height / 2;
    ctx.translate(cx, cy);
    ctx.rotate(obj.rotation * DEG);
    ctx.globalAlpha = obj.opacity ?? 1;

    if (obj.type === 'text') {
        const style = [
            obj.italic ? 'italic' : '',
            obj.bold ? 'bold' : '',
            `${obj.fontSize}px`,
            `"${obj.fontFamily}"`
        ]
            .filter(Boolean)
            .join(' ');
        ctx.font = style;
        ctx.fillStyle = obj.color ?? '#000000';
        ctx.textBaseline = 'top';

        // 逐行繪製
        const lines = obj.text.split('\n');
        const lineH = obj.fontSize * 1.2;
        lines.forEach((line, i) => {
            ctx.fillText(line, -obj.width / 2, -obj.height / 2 + i * lineH);
        });
    }

    if (obj.type === 'image' && obj.imageEl) {
        // 簡易亮度/對比 filter
        const b = obj.brightness ?? 0;
        const c = obj.contrast ?? 0;
        ctx.filter = `brightness(${100 + b}%) contrast(${100 + c}%)`;
        ctx.drawImage(obj.imageEl, -obj.width / 2, -obj.height / 2, obj.width, obj.height);
        ctx.filter = 'none';
    }

    ctx.restore();
}

function renderSelection(ctx, obj) {
    ctx.save();
    const cx = obj.x + obj.width / 2;
    const cy = obj.y + obj.height / 2;
    ctx.translate(cx, cy);
    ctx.rotate(obj.rotation * DEG); // ★ 正號，與 renderObject 一致
    // 虛線外框
    ctx.strokeStyle = 'rgba(60, 130, 191, 0.9)';
    ctx.lineWidth = 1.5;
    ctx.setLineDash([5, 3]);
    ctx.strokeRect(-obj.width / 2 - 2, -obj.height / 2 - 2, obj.width + 4, obj.height + 4);
    ctx.setLineDash([]);
    ctx.restore();
    // ── 把手（世界座標繪製）──
    const handles = getHandles(obj);
    // 角落把手
    handles.corners.forEach((h) => {
        ctx.save();
        ctx.fillStyle = '#ffffff';
        ctx.strokeStyle = 'rgb(60, 130, 191)';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.rect(h.x - HANDLE_SIZE / 2, h.y - HANDLE_SIZE / 2, HANDLE_SIZE, HANDLE_SIZE);
        ctx.fill();
        ctx.stroke();
        ctx.restore();
    });
    // 旋轉把手
    const rh = handles.rotate;
    ctx.save();
    ctx.fillStyle = 'rgb(60, 130, 191)';
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(rh.x, rh.y, HANDLE_SIZE / 2 + 2, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.restore();
    // 旋轉把手連線：從上邊中點到旋轉把手
    const tl = handles.corners.find((h) => h.id === 'tl');
    const tr = handles.corners.find((h) => h.id === 'tr');
    const midTopX = (tl.x + tr.x) / 2;
    const midTopY = (tl.y + tr.y) / 2;
    ctx.save();
    ctx.strokeStyle = 'rgb(60, 130, 191)';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(midTopX, midTopY);
    ctx.lineTo(rh.x, rh.y);
    ctx.stroke();
    ctx.restore();
}

// ─── 計算文字尺寸 ─────────────────────────────────
function measureText(obj, ctx) {
    const style = [
        obj.italic ? 'italic' : '',
        obj.bold ? 'bold' : '',
        `${obj.fontSize}px`,
        `"${obj.fontFamily}"`
    ]
        .filter(Boolean)
        .join(' ');
    ctx.font = style;
    const lines = obj.text.split('\n');
    const lineH = obj.fontSize * 1.2;
    let maxW = 0;
    lines.forEach((line) => {
        const w = ctx.measureText(line).width;
        if (w > maxW) maxW = w;
    });
    return {
        width: Math.max(maxW, 10),
        height: lineH * lines.length
    };
}

// ═══════════════════════════════════════════════════
// 主 Composable
// ═══════════════════════════════════════════════════
export function useCanvas() {
    const canvasEl = ref(null); // HTMLCanvasElement
    const objects = ref([]); // 所有物件
    const selectedId = ref(null); // 選取物件 ID
    const canvasBackground = ref('#ffffff');
    const isProductLoaded = ref(false);

    let ctx = null;
    let nextId = 1;
    let _onSelectCallback = null; // 通知外部選取變更

    // ─── 重設 Canvas 尺寸 ─────────────────────────
    const resizeCanvas = (width, height) => {
        if (!canvasEl.value) return;
        canvasEl.value.width = width;
        canvasEl.value.height = height;
        render();
    };
    // ─── 將超出範圍的物件夾回 Canvas 邊界內 ───────
    const clampObjects = (width, height) => {
        for (const obj of objects.value) {
            if (obj.x < 0) obj.x = 0;
            if (obj.y < 0) obj.y = 0;
            if (obj.x + obj.width > width) {
                obj.x = Math.max(0, width - obj.width);
            }
            if (obj.y + obj.height > height) {
                obj.y = Math.max(0, height - obj.height);
            }
        }
        render();
    };

    // ─── 選取/取消 callback 注冊 ────────────────────
    const onSelectChange = (cb) => {
        _onSelectCallback = cb;
    };

    const _notifySelect = (obj) => {
        if (_onSelectCallback) _onSelectCallback(obj);
    };

    // ─── 渲染 ────────────────────────────────────────
    const render = () => {
        if (!canvasEl.value || !ctx) return;
        const w = canvasEl.value.width;
        const h = canvasEl.value.height;

        ctx.clearRect(0, 0, w, h);

        // 背景
        ctx.fillStyle = canvasBackground.value;
        ctx.fillRect(0, 0, w, h);

        // 繪製所有物件
        for (const obj of objects.value) {
            renderObject(ctx, obj);
        }

        // 選取框
        const sel = getSelected();
        if (sel) {
            renderSelection(ctx, sel);
        }
    };

    // ─── 初始化 ──────────────────────────────────────
    const initCanvas = (canvasId, width = 800, height = 600) => {
        const el = document.getElementById(canvasId);
        if (!el) return;
        canvasEl.value = el;
        el.width = width;
        el.height = height;
        ctx = el.getContext('2d');

        _attachEvents(el);
        render();
    };

    // ─── 取得選取物件 ────────────────────────────────
    const getSelected = () => objects.value.find((o) => o.id === selectedId.value) ?? null;

    // ─── 選取物件 ────────────────────────────────────
    const selectObject = (id) => {
        selectedId.value = id;
        _notifySelect(getSelected());
        render();
    };

    const clearSelection = () => {
        selectedId.value = null;
        _notifySelect(null);
        render();
    };

    // ─── 新增文字 ────────────────────────────────────
    const addText = (text, config = {}) => {
        if (!ctx) return;
        const obj = {
            id: nextId++,
            type: 'text',
            text,
            fontFamily: config.fontFamily ?? 'Microsoft JhengHei',
            fontSize: config.fontSize ?? 40,
            color: config.color ?? '#000000',
            bold: config.bold ?? false,
            italic: config.italic ?? false,
            x: 100,
            y: 100,
            width: 0,
            height: 0,
            rotation: 0,
            opacity: 1,
            scaleX: 1,
            scaleY: 1
        };
        // 量測尺寸
        const size = measureText(obj, ctx);
        obj.width = size.width;
        obj.height = size.height;

        objects.value.push(obj);
        selectedId.value = obj.id;
        _notifySelect(obj);
        render();
    };

    // ─── 新增圖片 ────────────────────────────────────
    const addImage = (file) => {
        const reader = new FileReader();
        reader.onload = (e) => {
            const img = new Image();
            img.onload = () => {
                // 限制最大尺寸
                const maxW = canvasEl.value?.width ?? 800;
                const maxH = canvasEl.value?.height ?? 600;
                let w = img.naturalWidth;
                let h = img.naturalHeight;
                const ratio = w / h;
                if (w > maxW * 0.7) {
                    w = maxW * 0.7;
                    h = w / ratio;
                }
                if (h > maxH * 0.7) {
                    h = maxH * 0.7;
                    w = h * ratio;
                }

                const obj = {
                    id: nextId++,
                    type: 'image',
                    imageEl: img,
                    x: (maxW - w) / 2,
                    y: (maxH - h) / 2,
                    width: w,
                    height: h,
                    rotation: 0,
                    opacity: 1,
                    scaleX: 1,
                    scaleY: 1,
                    brightness: 0,
                    contrast: 0
                };
                objects.value.push(obj);
                selectedId.value = obj.id;
                _notifySelect(obj);
                render();
            };
            img.src = e.target.result;
        };
        reader.readAsDataURL(file);
    };

    // ─── 刪除選取 ────────────────────────────────────
    const deleteSelected = () => {
        if (!selectedId.value) return;
        objects.value = objects.value.filter((o) => o.id !== selectedId.value);
        clearSelection();
    };

    // ─── 清空畫布 ────────────────────────────────────
    const clearCanvas = () => {
        objects.value = [];
        clearSelection();
    };

    // ─── 更新選取物件屬性 ────────────────────────────
    const updateSelected = (patch) => {
        const obj = getSelected();
        if (!obj) return;
        Object.assign(obj, patch);

        // 文字需重新量測寬高
        if (
            obj.type === 'text' &&
            ctx &&
            ('text' in patch ||
                'fontSize' in patch ||
                'fontFamily' in patch ||
                'bold' in patch ||
                'italic' in patch)
        ) {
            const size = measureText(obj, ctx);
            obj.width = size.width;
            obj.height = size.height;
        }

        _notifySelect(obj); // 同步回 sidebar
        render();
    };

    // ─── 背景顏色 ────────────────────────────────────
    const setCanvasBackground = (color) => {
        canvasBackground.value = color;
        render();
    };

    // ─── 匯出 PNG ────────────────────────────────────
    const exportToPng = (multiplier = 2) => {
        if (!canvasEl.value || !ctx) return '';
        // 高解析度
        const w = canvasEl.value.width;
        const h = canvasEl.value.height;
        const offscreen = document.createElement('canvas');
        offscreen.width = w * multiplier;
        offscreen.height = h * multiplier;
        const offCtx = offscreen.getContext('2d');
        offCtx.scale(multiplier, multiplier);

        offCtx.fillStyle = canvasBackground.value;
        offCtx.fillRect(0, 0, w, h);
        for (const obj of objects.value) {
            renderObject(offCtx, obj);
        }
        return offscreen.toDataURL('image/png');
    };

    // ─── 預覽快照 ────────────────────────────────────
    const getPreviewUrl = () => {
        if (!canvasEl.value) return '';
        clearSelection();
        render();
        return canvasEl.value.toDataURL('image/png');
    };

    // ═══ 滑鼠事件 ════════════════════════════════════
    let _dragState = null; // { type, startX, startY, objId, origObj, handle }

    const _getPos = (el, e) => {
        const rect = el.getBoundingClientRect();
        const scaleX = el.width / rect.width;
        const scaleY = el.height / rect.height;
        return {
            x: (e.clientX - rect.left) * scaleX,
            y: (e.clientY - rect.top) * scaleY
        };
    };

    const _attachEvents = (el) => {
        el.addEventListener('mousedown', _onMouseDown);
        el.addEventListener('mousemove', _onMouseMove);
        el.addEventListener('mouseup', _onMouseUp);
        el.addEventListener('mouseleave', _onMouseUp);
    };

    const _onMouseDown = (e) => {
        const pos = _getPos(canvasEl.value, e);
        const sel = getSelected();

        // 先檢查把手
        if (sel) {
            const handles = getHandles(sel);
            const hit = hitHandle(handles, pos.x, pos.y);
            if (hit) {
                _dragState = {
                    type: hit === 'rotate' ? 'rotate' : 'resize',
                    handle: hit,
                    startX: pos.x,
                    startY: pos.y,
                    objId: sel.id,
                    origObj: { ...sel }
                };
                return;
            }
        }

        // 從上往下找點擊物件
        let found = null;
        for (let i = objects.value.length - 1; i >= 0; i--) {
            if (hitTest(objects.value[i], pos.x, pos.y)) {
                found = objects.value[i];
                break;
            }
        }

        if (found) {
            if (selectedId.value !== found.id) {
                selectedId.value = found.id;
                _notifySelect(found);
                render();
            }
            _dragState = {
                type: 'move',
                startX: pos.x,
                startY: pos.y,
                objId: found.id,
                origObj: { ...found }
            };
        } else {
            clearSelection();
        }
    };

    const _onMouseMove = (e) => {
        if (!_dragState) return;
        const pos = _getPos(canvasEl.value, e);
        const obj = objects.value.find((o) => o.id === _dragState.objId);
        if (!obj) return;

        const dx = pos.x - _dragState.startX;
        const dy = pos.y - _dragState.startY;
        const orig = _dragState.origObj;

        if (_dragState.type === 'move') {
            obj.x = orig.x + dx;
            obj.y = orig.y + dy;
            _notifySelect(obj);
            render();
            return;
        }

        if (_dragState.type === 'rotate') {
            const cx = orig.x + orig.width / 2;
            const cy = orig.y + orig.height / 2;
            // atan2 計算角度，+90 讓 0度 = 正上方
            const angle = Math.atan2(pos.y - cy, pos.x - cx) * (180 / Math.PI) + 90;
            // ★ 四捨五入並正規化到 0~360
            obj.rotation = ((Math.round(angle) % 360) + 360) % 360;
            _notifySelect(obj);
            render();
            return;
        }

        if (_dragState.type === 'resize') {
            _doResize(obj, orig, _dragState.handle, pos);
            render();
            return;
        }
    };

    const _onMouseUp = () => {
        _dragState = null;
    };

    const _doResize = (obj, orig, handle, pos) => {
        const cx = orig.x + orig.width / 2;
        const cy = orig.y + orig.height / 2;
        // ── 1. 將滑鼠位置轉到「本地座標系（反向旋轉）」──
        const local = rotatePoint(cx, cy, pos.x, pos.y, -orig.rotation);
        // ── 2. 定義「固定的對角點」（本地座標）──
        // 拖 tl → 固定點是 br
        // 拖 tr → 固定點是 bl
        // 拖 bl → 固定點是 tr
        // 拖 br → 固定點是 tl
        const anchorMap = {
            tl: { ax: orig.x + orig.width, ay: orig.y + orig.height },
            tr: { ax: orig.x, ay: orig.y + orig.height },
            br: { ax: orig.x, ay: orig.y },
            bl: { ax: orig.x + orig.width, ay: orig.y }
        };
        const { ax, ay } = anchorMap[handle];
        const minSize = 20;
        // ── 3. 依把手計算新的本地左上角與尺寸 ──
        let newX, newY, newW, newH;
        if (handle === 'br') {
            newW = Math.max(minSize, local.x - ax);
            newH = Math.max(minSize, local.y - ay);
            newX = ax;
            newY = ay;
        } else if (handle === 'bl') {
            newW = Math.max(minSize, ax - local.x);
            newH = Math.max(minSize, local.y - ay);
            newX = ax - newW;
            newY = ay;
        } else if (handle === 'tr') {
            newW = Math.max(minSize, local.x - ax);
            newH = Math.max(minSize, ay - local.y);
            newX = ax;
            newY = ay - newH;
        } else if (handle === 'tl') {
            newW = Math.max(minSize, ax - local.x);
            newH = Math.max(minSize, ay - local.y);
            newX = ax - newW;
            newY = ay - newH;
        }
        // ── 4. 本地新中心點 → 反推世界座標中心 ──
        const newLocalCx = newX + newW / 2;
        const newLocalCy = newY + newH / 2;
        // 把「本地新中心」從本地座標系轉回世界座標
        // 本地座標系是以 orig 中心為原點旋轉的，
        // 所以用原始中心 + 正向旋轉 轉回世界座標
        const worldCenter = rotatePoint(cx, cy, newLocalCx, newLocalCy, orig.rotation);
        // ── 5. 套用到物件 ──
        obj.width = newW;
        obj.height = newH;
        obj.x = worldCenter.x - newW / 2;
        obj.y = worldCenter.y - newH / 2;
        _notifySelect(obj);
    };

    // ─── Toolbar：縮放整個 canvas 顯示（transform scale）─
    // 縮放只影響 CSS，不影響實際畫布尺寸
    const zoomLevel = ref(100);
    const registerZoomChangeCallback = () => {}; // 相容舊介面，保留

    return {
        canvasEl,
        objects,
        selectedId,
        canvasBackground,
        isProductLoaded,
        zoomLevel,
        registerZoomChangeCallback,
        onSelectChange,
        initCanvas,
        getSelected,
        selectObject,
        clearSelection,
        addText,
        addImage,
        deleteSelected,
        clearCanvas,
        updateSelected,
        setCanvasBackground,
        exportToPng,
        getPreviewUrl,
        render,
        resizeCanvas,
        clampObjects
    };
}
