<template>
    <div class="p-canvas-container">
        <div class="canvas-content">
            <div class="canvas-toolbar">
                <div class="toolbar-group">
                    <button class="toolbar-btn" title="放大 (Ctrl +)" @click="$emit('zoom-in')">
                        <i class="fas fa-search-plus"></i>
                    </button>
                    <button class="toolbar-btn" title="縮小 (Ctrl -)" @click="$emit('zoom-out')">
                        <i class="fas fa-search-minus"></i>
                    </button>
                    <div class="zoom-display">{{ zoomLevel }}%</div>
                    <button class="toolbar-btn" title="重設縮放" @click="$emit('reset-view')">
                        <i class="fas fa-compress-arrows-alt"></i>
                    </button>
                </div>

                <div class="toolbar-group">
                    <button class="toolbar-btn" title="預覽" @click="$emit('open-preview')">
                        <i class="fas fa-eye"></i>
                        <span class="btn-label">預覽</span>
                    </button>
                    <div class="toolbar-divider"></div>
                    <button
                        class="toolbar-btn toolbar-btn--danger"
                        title="刪除選取 (Delete)"
                        @click="$emit('delete-selected')"
                    >
                        <i class="fas fa-trash-alt"></i>
                    </button>
                    <button
                        class="toolbar-btn toolbar-btn--danger"
                        title="清空畫布"
                        @click="handleClearCanvas"
                    >
                        <i class="fas fa-eraser"></i>
                    </button>
                </div>
            </div>

            <div ref="wrapperRef" class="canvas-wrapper">
                <div class="scene-layer" :style="sceneLayerStyle"></div>

                <div class="canvas-centering">
                    <div class="machine-stage" :style="stageStyle">
                        <img
                            v-if="machineImageLoaded && currentMachineImage"
                            class="machine-base-img"
                            :src="currentMachineImage"
                            alt="機台底圖"
                            draggable="false"
                        />

                        <div
                            v-else-if="!machineImageLoaded && currentMachineImage"
                            class="machine-placeholder"
                        >
                            <i class="fas fa-image"></i>
                            <span>機台圖載入中...</span>
                        </div>

                        <div v-else-if="machineImageError" class="machine-error">
                            <i class="fas fa-exclamation-triangle"></i>
                            <span>機台圖無法載入</span>
                        </div>

                        <div class="canvas-print-area" :style="printAreaStyle">
                            <canvas id="main-canvas" ref="canvasRef" class="design-canvas"></canvas>
                        </div>

                        <div class="print-area-border" :style="printAreaStyle"></div>
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>

<script setup>
    import { ref, computed, watch, onMounted } from 'vue';
    import { confirmDanger } from '../utils/swal.js';
    // ✅ 修正：從 products.js import，不從 .vue import
    import { SCENES, PRODUCTS_CONFIG } from '../config/products';

    const props = defineProps({
        zoomLevel: { type: Number, default: 100 },
        selectedMachine: { type: String, default: null },
        sceneBackground: { type: String, default: null }
    });

    const emit = defineEmits([
        'canvas-ready',
        'zoom-in',
        'zoom-out',
        'fit-screen',
        'reset-view',
        'clear-canvas',
        'delete-selected',
        'open-preview'
    ]);

    const wrapperRef = ref(null);
    const canvasRef = ref(null);

    /* ── 機台圖 ── */
    const currentProductConfig = computed(() => {
        if (!props.selectedMachine || props.selectedMachine === 'pure') return null;
        return PRODUCTS_CONFIG[props.selectedMachine] ?? null;
    });

    const currentMachineImage = computed(() => {
        return currentProductConfig.value?.baseImage ?? null;
    });

    const machineImageLoaded = ref(false);
    const machineImageError = ref(false);

    watch(
        currentMachineImage,
        (url) => {
            if (!url) {
                machineImageLoaded.value = false;
                machineImageError.value = false;
                return;
            }
            machineImageLoaded.value = false;
            machineImageError.value = false;

            const img = new Image();
            img.onload = () => {
                machineImageLoaded.value = true;
            };
            img.onerror = () => {
                machineImageError.value = true;
            };
            img.src = url;
        },
        { immediate: true }
    );

    /* ── Stage / PrintArea ── */
    const DEFAULT_STAGE = { width: 800, height: 600 }; // ✅ 對齊你的 canvasSize
    const DEFAULT_PRINT_AREA = { left: 250, top: 170, width: 290, height: 250 };

    const stageSize = computed(() => {
        // canvasSize 才是整張圖的尺寸
        return currentProductConfig.value?.canvasSize ?? DEFAULT_STAGE;
    });
    const printArea = computed(() => {
        // 直接讀 printArea，由 createProduct 自動算好
        return currentProductConfig.value?.printArea ?? DEFAULT_PRINT_AREA;
    });

    const stageStyle = computed(() => ({
        width: `${stageSize.value.width}px`,
        height: `${stageSize.value.height}px`
    }));

    const printAreaStyle = computed(() => ({
        left: `${printArea.value.left}px`,
        top: `${printArea.value.top}px`,
        width: `${printArea.value.width}px`,
        height: `${printArea.value.height}px`
    }));

    /* ── 場景背景 ── */
    const sceneLayerStyle = computed(() => {
        if (!props.sceneBackground) return {};

        const scene = SCENES.find((s) => s.id === props.sceneBackground);
        if (!scene) return {};

        return {
            backgroundImage: `url(${scene.url})`,
            backgroundSize: 'cover',
            backgroundPosition: 'center',
            backgroundRepeat: 'no-repeat'
        };
    });

    /* ── 清空畫布 ── */
    const handleClearCanvas = async () => {
        const { isConfirmed } = await confirmDanger(
            '清空畫布',
            '確定要清空畫布嗎？所有內容將被刪除。',
            '確定清空'
        );
        if (isConfirmed) emit('clear-canvas');
    };

    /* ── 初始化 ── */
    onMounted(() => {
        emit('canvas-ready', {
            wrapperEl: wrapperRef.value,
            printArea: printArea.value
        });
    });

    watch(printArea, (newArea) => {
        emit('canvas-ready', {
            wrapperEl: wrapperRef.value,
            printArea: newArea
        });
    });

    defineExpose({ wrapperRef, canvasRef });
</script>

